/**
 * `skills install` — install the package's coding-agent skills into
 * `~/.cursor/skills/bdk/` without running `init`. `skills list` shows
 * each shipped skill and the version of its installed copy.
 *
 * Never prompts: running the command is the confirmation. The interactive
 * offer lives in `init`. Consumer `npm install` / `npx` copies the same
 * skills in postinstall (with `alwaysApply: true` so Cursor injects them);
 * this command refreshes them without reinstalling.
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { DEFAULT_LIST_LIMIT, nextPageHint, pageLocally, printListJson } from "./cli/output.js";
import { CLI_COMMAND_NAME } from "./distribution.js";
import { parseYamlFrontmatter } from "./frontmatter.js";
import { formatSkillInstall, installCursorSkills, installedSkillVersion, listShippedPackageSkills, planSkillInstall, cursorSkillsHome, skillInstallPath, } from "./install-cursor-skills.js";
import { stdoutPalette } from "./terminal-style.js";
export async function cmdInstallSkills(options = {}) {
    const out = options.out ?? ((text) => process.stdout.write(text));
    const err = options.err ?? ((text) => process.stderr.write(text));
    const plan = await planSkillInstall({
        packageRoot: options.packageRoot,
        skillsHome: options.skillsHome,
    });
    if (plan.shipped.length === 0) {
        err(`${CLI_COMMAND_NAME} ships no skills to install.\n`);
        return 1;
    }
    const emit = (run) => {
        const payload = {
            ok: true,
            dryRun: run.dryRun,
            directory: plan.directory,
            firstInstall: plan.firstInstall,
            skills: plan.leaves,
            removed: run.removed,
        };
        out(`${JSON.stringify(payload, null, 2)}\n`);
    };
    const noun = plan.shipped.length === 1 ? "skill" : "skills";
    if (options.print === true) {
        if (options.json === true) {
            emit({ dryRun: true, removed: plan.orphans });
            return 0;
        }
        const action = plan.firstInstall ? "install" : "update";
        out(`Would ${action} ${plan.leaves.length} BDK ${noun}\n`);
        out(previewBlock(plan));
        return 0;
    }
    const result = await installCursorSkills(plan.shipped, plan.skillsHome);
    if (options.json === true) {
        emit({ dryRun: false, removed: result.removed });
        return 0;
    }
    out(formatSkillInstall(plan, result));
    return 0;
}
function previewBlock(plan) {
    const c = stdoutPalette();
    const lines = [c.dim(`  skills:   ${plan.leaves.join(", ")}`)];
    if (plan.orphans.length > 0) {
        lines.push(`  removes:  ${plan.orphans.join(", ")}`);
    }
    for (const dir of plan.legacyDirs) {
        lines.push(`  removes:  ${dir}`);
    }
    lines.push(`  location: ${plan.directory}`);
    return `${lines.join("\n")}\n`;
}
/** `skills list` — the shipped skills, and which installed copies are stale. */
export async function cmdListSkills(options = {}) {
    const out = options.out ?? ((text) => process.stdout.write(text));
    const err = options.err ?? ((text) => process.stderr.write(text));
    const skillsHome = options.skillsHome ?? cursorSkillsHome();
    const shipped = await listShippedPackageSkills(options.packageRoot);
    const all = await Promise.all(shipped.map(async (skill) => {
        const source = await readFile(join(skill.sourceDir, "SKILL.md"), "utf8");
        const description = parseYamlFrontmatter(source).data.description;
        const path = skillInstallPath(skill, skillsHome);
        let installedVersion;
        try {
            installedVersion =
                installedSkillVersion(await readFile(join(path, "SKILL.md"), "utf8")) ?? "unknown";
        }
        catch {
            installedVersion = null;
        }
        return {
            name: skill.name,
            description: typeof description === "string" ? description.trim() : "",
            version: skill.packageVersion,
            installedVersion,
            path,
        };
    }));
    const page = pageLocally(all, {
        limit: options.limit ?? DEFAULT_LIST_LIMIT,
        pageToken: options.pageToken,
    });
    if (options.json === true) {
        printListJson(page, { fields: options.fields, write: out });
        return 0;
    }
    const c = stdoutPalette();
    const width = Math.max(...page.items.map((item) => item.name.length), 0);
    for (const item of page.items) {
        const status = item.installedVersion === null
            ? "not installed"
            : item.installedVersion === item.version
                ? `installed ${item.version}`
                : `installed ${item.installedVersion}, ships ${item.version}`;
        out(`${item.name.padEnd(width)}  ${status}\n`);
        out(c.dim(`  ${item.description}\n`));
    }
    const stale = all.some((item) => item.installedVersion !== item.version);
    if (stale) {
        err(`Run \`${CLI_COMMAND_NAME} skills install\` to install or refresh them.\n`);
    }
    const hint = nextPageHint(page.nextPageToken);
    if (hint !== undefined) {
        err(hint);
    }
    return 0;
}
